<?php
declare(strict_types=1);
namespace StageArtCore\Presentation\Rest;
use StageArtCore\Domain\Member\MemberRepository;use WP_REST_Request;use WP_REST_Server;
final class MemberController{public function register_routes():void{register_rest_route('stageart/v1','/members',['methods'=>WP_REST_Server::READABLE,'callback'=>[$this,'index'],'permission_callback'=>'__return_true']);register_rest_route('stageart/v1','/members/(?P<slug>[a-zA-Z0-9_-]+)',['methods'=>WP_REST_Server::READABLE,'callback'=>[$this,'show'],'permission_callback'=>'__return_true']);register_rest_route('stageart/v1','/admin/members',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[$this,'store'],'permission_callback'=>[$this,'admin']]);register_rest_route('stageart/v1','/admin/members/(?P<id>\d+)',['methods'=>WP_REST_Server::EDITABLE,'callback'=>[$this,'update'],'permission_callback'=>[$this,'admin']]);}private function admin():bool{return current_user_can('manage_options');}private function publicData(array$m):array{$m['roles']=array_map(fn($r)=>MemberRepository::ROLES[$r]??$r,$m['roles']??[]);unset($m['status']);return$m;}public function index():array{$repo=new MemberRepository();return array_map([$this,'publicData'],$repo->all(true));}public function show(WP_REST_Request$request){$m=(new MemberRepository())->findBySlug((string)$request['slug']);if(!$m||$m['status']!=='published')return new \WP_Error('not_found','メンバーが見つかりません。',['status'=>404]);return$this->publicData($m);}public function store(WP_REST_Request$r){$p=$r->get_json_params();if(empty($p['name']))return new \WP_Error('invalid_name','名前は必須です。',['status'=>400]);return(new MemberRepository())->save((array)$p);}public function update(WP_REST_Request$r){$p=$r->get_json_params();$p['id']=(int)$r['id'];if(empty($p['name']))return new \WP_Error('invalid_name','名前は必須です。',['status'=>400]);return(new MemberRepository())->save((array)$p);}}
